CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY AUTOINCREMENT, usn TEXT NOT NULL UNIQUE, name TEXT NOT NULL, department TEXT NOT NULL, year INTEGER NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS faculty (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, department TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'FACULTY' CHECK (role IN ('FACULTY','HOD')), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS requests (request_id TEXT PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id), type TEXT NOT NULL CHECK (type IN ('Bonafide Certificate','Leave Request','Lab Issue','Scholarship Issue','Academic Query','Other')), description TEXT NOT NULL, priority TEXT NOT NULL CHECK (priority IN ('HIGH','MEDIUM','LOW')), status TEXT NOT NULL CHECK (status IN ('SUBMITTED','PENDING','ASSIGNED','IN_PROGRESS','RESOLVED','ESCALATED','REJECTED')), assigned_faculty INTEGER REFERENCES faculty(id), escalation_level TEXT NOT NULL DEFAULT 'FACULTY', faculty_response TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS request_history (history_id INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT NOT NULL REFERENCES requests(request_id), old_status TEXT, new_status TEXT NOT NULL, changed_by TEXT NOT NULL, timestamp TEXT NOT NULL, comment TEXT);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, recipient_role TEXT NOT NULL, recipient_id INTEGER NOT NULL, message TEXT NOT NULL, request_id TEXT, is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS registrations (id INTEGER PRIMARY KEY AUTOINCREMENT, usn TEXT NOT NULL UNIQUE, name TEXT NOT NULL, email TEXT NOT NULL, department TEXT NOT NULL, year INTEGER NOT NULL, password TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT NOT NULL REFERENCES requests(request_id), filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, data BLOB NOT NULL, uploaded_by TEXT NOT NULL, created_at TEXT NOT NULL);
